import json
import itertools

def solve_puzzle():
    houses = [1, 2, 3, 4]  # from left to right
    names = ["Alice", "Arnold", "Peter", "Eric"]
    hair_colors = ["black", "blonde", "brown", "red"]

    solutions = []

    # Iterate over all possible assignments of names to houses
    for name_perm in itertools.permutations(names):
        # Clue 5: Alice is in the first house.
        if name_perm[0] != "Alice":
            continue

        # Clue 2: Alice and Arnold are next to each other.
        pos_alice = name_perm.index("Alice")
        pos_arnold = name_perm.index("Arnold")
        if abs(pos_alice - pos_arnold) != 1:
            continue

        # Iterate over all possible assignments of hair colors to houses
        for hair_perm in itertools.permutations(hair_colors):
            # Clue 4: The person who has black hair is not in the first house.
            if hair_perm[0] == "black":
                continue

            # Clue 3: Eric is the person who has brown hair.
            pos_eric = name_perm.index("Eric")
            if hair_perm[pos_eric] != "brown":
                continue

            # Clue 1: Eric is directly left of the person who has blonde hair.
            if pos_eric == len(houses) - 1:
                continue  # Eric cannot be at the last house if directly left of someone
            if hair_perm[pos_eric + 1] != "blonde":
                continue

            # All constraints satisfied, record solution
            assignment = []
            for i, house in enumerate(houses):
                assignment.append([str(house), name_perm[i], hair_perm[i]])
            solutions.append(assignment)

    # Prepare JSON output with the first (should be unique) solution
    result = {
        "solution": {
            "header": ["House", "Name", "HairColor"],
            "rows": solutions[0] if solutions else []
        }
    }
    return result

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
